package events_test

import (
	"encoding/json"
	"testing"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
)

// compactSeed commits three changes and a snapshot at cursor 2, so a
// compaction trims c1 and c2 and leaves c3 online.
func compactSeed(t *testing.T, s *app.App) {
	t.Helper()
	if _, err := s.RegisterDevice("dev-1"); err != nil {
		t.Fatal(err)
	}
	if _, err := s.PostChanges("doc", changes("c1", "c2", "c3")); err != nil {
		t.Fatal(err)
	}
	created, err := s.PutSnapshot("doc", 2, json.RawMessage(`{"s":1}`))
	if err != nil || !created {
		t.Fatalf("snapshot: created=%v err=%v", created, err)
	}
}

func TestCompactTrimsOnlineLogAndRetainsSummaries(t *testing.T) {
	s, err := app.Open("")
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = s.Close() }()
	compactSeed(t, s)

	boundary, removed, err := s.CompactChanges("doc", "dev-1")
	if err != nil {
		t.Fatal(err)
	}
	if boundary != 2 || removed != 2 {
		t.Fatalf("compact = boundary %d removed %d, want 2/2", boundary, removed)
	}

	// The trimmed rows are gone from the online log; only the tail remains.
	var online int
	if err := s.DB().QueryRow(
		`SELECT COUNT(*) FROM changes WHERE document_id = 'doc'`,
	).Scan(&online); err != nil {
		t.Fatal(err)
	}
	if online != 1 {
		t.Fatalf("online rows = %d, want 1", online)
	}

	// Each trimmed id keeps exactly one fixed-size summary: the source device
	// and a 32-byte digest stand in for the payload, so storage does not grow
	// back to the pre-compaction shape.
	var summaries int
	var maxDigest int
	if err := s.DB().QueryRow(
		`SELECT COUNT(*), COALESCE(MAX(LENGTH(digest)), 0) FROM change_identities WHERE document_id = 'doc'`,
	).Scan(&summaries, &maxDigest); err != nil {
		t.Fatal(err)
	}
	if summaries != 2 || maxDigest != 32 {
		t.Fatalf("summaries = %d max digest %d, want 2 summaries of 32 bytes", summaries, maxDigest)
	}

	// A repeat compaction trims nothing and reports the same boundary.
	boundary, removed, err = s.CompactChanges("doc", "dev-1")
	if err != nil {
		t.Fatal(err)
	}
	if boundary != 2 || removed != 0 {
		t.Fatalf("re-compact = boundary %d removed %d, want 2/0", boundary, removed)
	}
}

func TestCompactBoundaryAndCursorSpaceSurviveFullTrim(t *testing.T) {
	s, err := app.Open("")
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = s.Close() }()

	if _, err := s.RegisterDevice("dev-1"); err != nil {
		t.Fatal(err)
	}
	if _, err := s.PostChanges("doc", changes("c1", "c2")); err != nil {
		t.Fatal(err)
	}
	if _, err := s.PutSnapshot("doc", 2, json.RawMessage(`null`)); err != nil {
		t.Fatal(err)
	}
	boundary, removed, err := s.CompactChanges("doc", "dev-1")
	if err != nil {
		t.Fatal(err)
	}
	if boundary != 2 || removed != 2 {
		t.Fatalf("compact = boundary %d removed %d, want 2/2", boundary, removed)
	}

	// The document stays known even with no online row: an empty read reports
	// the boundary, and the cursor space continues past it.
	exists, err := s.DocumentExists("doc")
	if err != nil || !exists {
		t.Fatalf("fully trimmed document exists = %v, err = %v", exists, err)
	}
	list, next, err := s.ListChanges("doc", 0, 100)
	if err != nil {
		t.Fatal(err)
	}
	if len(list) != 0 || next != 2 {
		t.Fatalf("list = %v next = %d, want empty with the boundary 2", list, next)
	}
	results, err := s.PostChanges("doc", changes("c3"))
	if err != nil {
		t.Fatal(err)
	}
	if !results[0].Created || results[0].Cursor != 3 {
		t.Fatalf("post after full trim = %+v, want created cursor 3", results[0])
	}
}

func TestCompactGateAndUnknownDocument(t *testing.T) {
	s, err := app.Open("")
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = s.Close() }()

	// An unregistered device is rejected before anything is observed.
	if _, _, err := s.CompactChanges("doc", "ghost"); err == nil {
		t.Fatal("unregistered device compacted without error")
	}

	// An unknown document compacts successfully with boundary 0.
	if _, err := s.RegisterDevice("dev-1"); err != nil {
		t.Fatal(err)
	}
	boundary, removed, err := s.CompactChanges("ghost-doc", "dev-1")
	if err != nil {
		t.Fatal(err)
	}
	if boundary != 0 || removed != 0 {
		t.Fatalf("unknown compact = boundary %d removed %d, want 0/0", boundary, removed)
	}

	// A revoked device is denied and writes nothing.
	if _, err := s.SetDocumentPermission("doc", "dev-1", false); err != nil {
		t.Fatal(err)
	}
	if _, _, err := s.CompactChanges("doc", "dev-1"); err == nil {
		t.Fatal("revoked device compacted without error")
	}
}

package events

import (
	"context"
	"time"
)

// DocumentExists reports whether documentID is a known document rather than an
// empty namespace: it has any online change row, or a compaction boundary from
// a log that was (fully or partially) trimmed.
func (s *Service) DocumentExists(documentID string) (bool, error) {
	var known bool
	if err := s.db.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM changes WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM change_boundaries WHERE document_id = ?)`,
		documentID, documentID,
	).Scan(&known); err != nil {
		return false, err
	}
	return known, nil
}

// ListChanges returns at most limit changes for documentID whose cursor is
// greater than after and still online, in cursor order, together with the
// cursor to pass as the next after value. An unknown document yields an empty
// list and cursor 0; a known document with no rows past after yields
// nextCursor == max(after, boundary), so a caller positioned inside the
// trimmed range resumes from the compaction boundary.
func (s *Service) ListChanges(documentID string, after, limit int64) ([]ListedChange, int64, error) {
	rows, err := s.db.Query(
		`SELECT id, device_id, payload, cursor FROM changes
		 WHERE document_id = ? AND cursor > ?
		 ORDER BY cursor ASC
		 LIMIT ?`,
		documentID, after, limit,
	)
	if err != nil {
		return nil, 0, err
	}
	defer func() { _ = rows.Close() }()

	out := make([]ListedChange, 0)
	var maxCursor int64 = after
	for rows.Next() {
		var c ListedChange
		if err := rows.Scan(&c.ID, &c.DeviceID, &c.Payload, &c.Cursor); err != nil {
			return nil, 0, err
		}
		out = append(out, c)
		maxCursor = c.Cursor
	}
	if err := rows.Err(); err != nil {
		return nil, 0, err
	}

	// Distinguish an unknown document from a known one with nothing new:
	// unknown documents must report nextCursor 0, while a known document
	// reports the greater of after and the compaction boundary.
	if len(out) == 0 {
		known, err := s.DocumentExists(documentID)
		if err != nil {
			return nil, 0, err
		}
		if !known {
			return out, 0, nil
		}
		boundary, err := boundaryOfTx(s.db, documentID)
		if err != nil {
			return nil, 0, err
		}
		if boundary > maxCursor {
			maxCursor = boundary
		}
	}
	return out, maxCursor, nil
}

// WaitForChanges blocks until documentID has a change with cursor greater than
// after, a change is committed while waiting, wait elapses, ctx is canceled
// (the client disconnected) or the service stops. It then returns the current
// page of up to limit changes exactly as ListChanges would, with timedOut=true
// only when the wait deadline expired with no new rows.
//
// Registration precedes the first query: a commit landing between the read and
// the park still notifies a registered channel, so no change is missed.
//
// An unknown document is never parked on: it returns immediately with an empty
// list and nextCursor 0, timedOut=false. Data already past after is likewise
// returned immediately. wait <= 0 is an immediately expired deadline.
func (s *Service) WaitForChanges(ctx context.Context, documentID string, after, limit int64, wait time.Duration) (changes []ListedChange, nextCursor int64, timedOut bool, err error) {
	ch, remove := s.registerWait(documentID)
	defer remove()

	changes, nextCursor, err = s.ListChanges(documentID, after, limit)
	if err != nil || len(changes) > 0 {
		return changes, nextCursor, false, err
	}

	// Empty page: distinguish an unknown document (immediate empty/0, never
	// parked on) from a known document caught up to after.
	known, err := s.DocumentExists(documentID)
	if err != nil || !known {
		return changes, 0, false, err
	}

	// Known document, nothing new: a zero wait is an immediately expired
	// deadline; ListChanges already echoes nextCursor == after.
	if wait <= 0 {
		return changes, nextCursor, true, nil
	}

	timer := time.NewTimer(wait)
	defer timer.Stop()

	select {
	case <-ch:
		// Woken by a committed change or by InterruptWaits.
		s.mu.Lock()
		closing := s.closed
		s.mu.Unlock()
		if closing {
			return nil, 0, false, ErrStoreClosing
		}
		changes, nextCursor, err = s.ListChanges(documentID, after, limit)
		return changes, nextCursor, len(changes) == 0, err
	case <-timer.C:
		// Timeout with no new rows: echo the caller's cursor without
		// advancing it. The document was known above, so ListChanges returns
		// nextCursor == after for an empty page.
		changes, nextCursor, err = s.ListChanges(documentID, after, limit)
		return changes, nextCursor, len(changes) == 0, err
	case <-ctx.Done():
		return nil, 0, false, ctx.Err()
	}
}

// registerWait parks a channel for documentID and returns it together with a
// removal function. The channel is closed on the next committed change to the
// document, or when the service stops.
func (s *Service) registerWait(documentID string) (ch chan struct{}, remove func()) {
	ch = make(chan struct{}, 1)

	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		// Shutdown beat the registration: signal immediately so the caller does
		// not park on a channel nobody will close.
		close(ch)
		return ch, func() {}
	}
	s.nextWait++
	id := s.nextWait
	set := s.waits[documentID]
	if set == nil {
		set = make(map[uint64]chan struct{})
		s.waits[documentID] = set
	}
	set[id] = ch
	return ch, func() {
		s.mu.Lock()
		if set, ok := s.waits[documentID]; ok {
			delete(set, id)
			if len(set) == 0 {
				delete(s.waits, documentID)
			}
		}
		s.mu.Unlock()
	}
}

// notifyWaiters signals every long poll parked on documentID and every
// subscription open on it. It is called only after a change-bearing
// transaction has committed, so parked readers observe the new rows when they
// re-query and pushed frames describe committed changes.
func (s *Service) notifyWaiters(documentID string) {
	s.mu.Lock()
	set := s.waits[documentID]
	delete(s.waits, documentID)
	s.mu.Unlock()
	for _, ch := range set {
		close(ch)
	}
	s.signalSubscribers(documentID)
}

// Package store is the durable kernel shared by the internal services: it
// owns the SQLite database handle and the registration layer (devices and
// sessions) plus resumable attachments.
//
// The business services layered on top of the kernel — the change event log,
// the permission ledger and the CRDT state — live in their own packages and
// cooperate only through their internal interfaces. They all share this one
// handle: it opens a single pooled connection with immediate write
// transactions, so every service's transactional judgment is serialized on
// the same connection and no batch is ever half written.
//
// Devices and sessions form the registration layer. A device registers with a
// client-supplied id; a session belongs to exactly one registered device and
// is addressed by its own client-supplied id. Registration and session
// creation are idempotent re-posts: the first call creates, an identical
// repeat does not. A session id already owned by another device is a
// conflict, never silently re-homed. Deletes are owner-scoped and hard: a
// repeat delete, another device, and a cross-device path all miss with 404,
// after which the id is free to be created again. A device itself can
// deregister: the device row and everything it owns — its sessions and the
// attachments it created, chunks and grants included — vanish in one
// serialized transaction, a repeat or never-registered deregistration misses
// with 404 and writes nothing, and the freed id registers again as a
// brand-new device.
//
// Attachments are resumable chunked uploads owned by the registered device
// that created them. Creation pins the declared total size, chunk size and
// SHA-256 digest; chunks land in any order and are stored durably as they
// arrive, so an interrupted upload resumes after a restart with its
// idempotency and conflict decisions intact. Finishing concatenates the
// chunks, verifies the digest and seals the upload; a sealed upload is
// immutable and rejects every further chunk write. Finished content is
// addressed by digest, so a second attachment with the same digest and size
// reuses the stored bytes instead of copying them. The creator may grant
// other registered devices read-only access per attachment; every
// (attachment, device) pair starts unauthorized, grants and revokes commit in
// the same serialized way, and access never widens the write paths. Deletes
// are owner-scoped and hard: the record, its chunks and its grants vanish in
// one serialized transaction, a repeat delete misses with 404, the id is free
// to be created again, and the shared content bytes are reclaimed once the
// last completed attachment referencing them is gone.
package store

import (
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"

	_ "modernc.org/sqlite"
)

// ErrDeviceNotFound reports that an operation targets a device id that was
// never registered. Services map it to 404; nothing is written.
var ErrDeviceNotFound = errors.New("device not found")

// ErrPermissionDenied reports that a device's access to a document has been
// revoked. Services map it to 403; nothing is written and no document content
// is exposed. It is a shared verdict produced by the permission service and
// consulted by every service that enforces the gate inside a transaction.
var ErrPermissionDenied = errors.New("device permission for this document has been revoked")

// ErrSessionConflict reports that a session id already belongs to a different
// device. The session keeps its original owner; nothing is written. Services
// map it to 409.
type ErrSessionConflict struct {
	ID string
}

func (e *ErrSessionConflict) Error() string {
	return fmt.Sprintf("session %q belongs to another device", e.ID)
}

// ErrSessionNotFound reports that no live session matches the (device,
// session) pair: the session was never created, was already deleted, or
// belongs to another device. Services map it to 404.
var ErrSessionNotFound = errors.New("session not found")

// DBTX is the subset of *sql.DB and *sql.Tx the services use for their
// serialized work, so judgments made "in the same transaction" (for example a
// permission gate followed by the gated write) run on one concrete connection
// whether the caller holds a transaction or the handle itself.
type DBTX interface {
	Exec(query string, args ...any) (sql.Result, error)
	Query(query string, args ...any) (*sql.Rows, error)
	QueryRow(query string, args ...any) *sql.Row
}

// Store is the durable kernel: one SQLite database handle together with the
// device, session and attachment data it owns.
type Store struct {
	db *sql.DB
}

// Open opens (creating if needed) the SQLite database at path. The empty path
// opens an in-memory database useful for tests.
func Open(path string) (*Store, error) {
	if path == "" {
		// With a single pooled connection this is a private, per-instance
		// in-memory database (useful for tests).
		path = "file::memory:"
	}
	// _txlock=immediate makes writers acquire the write lock at BEGIN, so
	// concurrent batches serialize without SQLITE_BUSY deadlocks.
	dsn := path + "?_txlock=immediate&_busy_timeout=5000&_journal_mode=WAL&_synchronous=FULL&_foreign_keys=on"
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, err
	}
	// One connection avoids cross-connection locking surprises; writes are
	// serialized by the immediate transaction anyway, and SQLite concurrency
	// for readers does not help correctness here. It also keeps every
	// service's transaction serialized on the same connection.
	db.SetMaxOpenConns(1)
	s := &Store{db: db}
	if err := s.init(); err != nil {
		_ = db.Close()
		return nil, err
	}
	return s, nil
}

// DB returns the underlying handle. The business services use it to open the
// serialized transactions their judgments run in; callers outside the
// internal packages never need it.
func (s *Store) DB() *sql.DB { return s.db }

// Close releases the database handle.
func (s *Store) Close() error {
	return s.db.Close()
}

func (s *Store) init() error {
	_, err := s.db.Exec(`
CREATE TABLE IF NOT EXISTS devices (
	id TEXT NOT NULL PRIMARY KEY
);
CREATE TABLE IF NOT EXISTS sessions (
	id        TEXT NOT NULL PRIMARY KEY,
	device_id TEXT NOT NULL REFERENCES devices(id)
);
CREATE INDEX IF NOT EXISTS sessions_device_idx
	ON sessions(device_id);
CREATE TABLE IF NOT EXISTS attachments (
	id          TEXT NOT NULL PRIMARY KEY,
	device_id   TEXT NOT NULL REFERENCES devices(id),
	total_bytes INTEGER NOT NULL,
	chunk_size  INTEGER NOT NULL,
	sha256      TEXT NOT NULL,
	complete    INTEGER NOT NULL DEFAULT 0,
	reused      INTEGER NOT NULL DEFAULT 0,
	created_seq INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS attachment_chunks (
	attachment_id TEXT NOT NULL REFERENCES attachments(id),
	idx           INTEGER NOT NULL,
	data          BLOB NOT NULL,
	PRIMARY KEY (attachment_id, idx)
);
CREATE TABLE IF NOT EXISTS attachment_contents (
	sha256 TEXT NOT NULL PRIMARY KEY,
	size   INTEGER NOT NULL,
	data   BLOB NOT NULL
);
CREATE TABLE IF NOT EXISTS attachment_access (
	attachment_id TEXT NOT NULL REFERENCES attachments(id),
	device_id     TEXT NOT NULL,
	authorized    INTEGER NOT NULL,
	granted_seq   INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY (attachment_id, device_id)
);
`)
	if err != nil {
		return err
	}
	if err := s.ensureAttachmentCreatedSeq(); err != nil {
		return err
	}
	return s.ensureAttachmentAccessGrantedSeq()
}

// ensureAttachmentCreatedSeq adds the creation-order column to databases
// created before it existed. Existing rows are backfilled in insertion
// (rowid) order so their relative listing order is unchanged; new rows take
// strictly larger values, so the sequence never reuses a value even after
// the newest attachment is deleted and its id created again.
func (s *Store) ensureAttachmentCreatedSeq() error {
	rows, err := s.db.Query(`PRAGMA table_info(attachments)`)
	if err != nil {
		return err
	}
	hasColumn := false
	for rows.Next() {
		var cid, notNull, pk int
		var name, colType string
		var dflt sql.NullString
		if err := rows.Scan(&cid, &name, &colType, &notNull, &dflt, &pk); err != nil {
			_ = rows.Close()
			return err
		}
		if name == "created_seq" {
			hasColumn = true
		}
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	_ = rows.Close()
	if hasColumn {
		return nil
	}
	if _, err := s.db.Exec(
		`ALTER TABLE attachments ADD COLUMN created_seq INTEGER NOT NULL DEFAULT 0`,
	); err != nil {
		return err
	}
	_, err = s.db.Exec(
		`UPDATE attachments SET created_seq = (
			SELECT COUNT(*) FROM attachments older WHERE older.rowid <= attachments.rowid
		)`,
	)
	return err
}

// ensureAttachmentAccessGrantedSeq adds the grant-order column to access
// tables created before it existed. Existing rows are backfilled one past the
// per-attachment maximum in insertion (rowid) order, so surviving grants keep
// a stable relative order; every new grant takes a strictly larger value, even
// after the previously newest grant was revoked, so a re-granted device lists
// at the position of its latest grant and a value is never reused.
func (s *Store) ensureAttachmentAccessGrantedSeq() error {
	rows, err := s.db.Query(`PRAGMA table_info(attachment_access)`)
	if err != nil {
		return err
	}
	hasColumn := false
	for rows.Next() {
		var cid, notNull, pk int
		var name, colType string
		var dflt sql.NullString
		if err := rows.Scan(&cid, &name, &colType, &notNull, &dflt, &pk); err != nil {
			_ = rows.Close()
			return err
		}
		if name == "granted_seq" {
			hasColumn = true
		}
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	_ = rows.Close()
	if hasColumn {
		return nil
	}
	if _, err := s.db.Exec(
		`ALTER TABLE attachment_access ADD COLUMN granted_seq INTEGER NOT NULL DEFAULT 0`,
	); err != nil {
		return err
	}
	_, err = s.db.Exec(
		`UPDATE attachment_access SET granted_seq = (
			SELECT rn FROM (
				SELECT rowid AS rid,
				       ROW_NUMBER() OVER (PARTITION BY attachment_id ORDER BY rowid) AS rn
				FROM attachment_access
			) WHERE rid = attachment_access.rowid
		)`,
	)
	return err
}

// RegisterDevice registers a device by client-supplied id. The first call for
// an id creates it and reports created=true; repeating the registration is
// idempotent (created=false). Device identity never changes.
func (s *Store) RegisterDevice(deviceID string) (created bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	created, err = RegisterDeviceTx(tx, deviceID)
	if err != nil {
		return false, err
	}
	return created, tx.Commit()
}

// RegisterDeviceTx is RegisterDevice against an existing transaction, so the
// services can resolve the registration layer as the first step of a larger
// serialized transaction (their permission/content gates then share it).
func RegisterDeviceTx(q DBTX, deviceID string) (created bool, err error) {
	var exists bool
	if err := q.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&exists); err != nil {
		return false, err
	}
	if !exists {
		if _, err := q.Exec(`INSERT INTO devices (id) VALUES (?)`, deviceID); err != nil {
			return false, err
		}
		return true, nil
	}
	return false, nil
}

// DeviceExistsTx reports whether deviceID is registered, evaluated inside q so
// a service's gate runs on the same transaction as the work it guards.
func DeviceExistsTx(q DBTX, deviceID string) (bool, error) {
	var exists bool
	if err := q.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&exists); err != nil {
		return false, err
	}
	return exists, nil
}

// CreateSession creates a session owned by deviceID with a client-supplied id.
//
//   - An unknown device yields ErrDeviceNotFound; nothing is written.
//   - A session id already owned by another device yields *ErrSessionConflict;
//     nothing is written and the owner is unchanged.
//   - Re-posting the same (device, session) pair is idempotent: created=false.
//
// A deleted session is gone for good, so its id can be registered again as a
// brand-new session (created=true). The lookup, owner check and insert run in
// one serialized transaction, so concurrent creates of the same session id
// cannot both create it.
func (s *Store) CreateSession(deviceID, sessionID string) (created bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	var deviceExists bool
	if err := tx.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&deviceExists); err != nil {
		return false, err
	}
	if !deviceExists {
		return false, ErrDeviceNotFound
	}

	var owner string
	err = tx.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&owner)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		if _, err := tx.Exec(
			`INSERT INTO sessions (id, device_id) VALUES (?, ?)`,
			sessionID, deviceID,
		); err != nil {
			return false, err
		}
		if err := tx.Commit(); err != nil {
			return false, err
		}
		return true, nil
	case err != nil:
		return false, err
	}

	if owner != deviceID {
		return false, &ErrSessionConflict{ID: sessionID}
	}
	return false, tx.Commit()
}

// DeleteSession removes the live session matching the (deviceID, sessionID)
// pair. Any miss — the session does not exist, was already deleted, or belongs
// to another device — returns ErrSessionNotFound and changes nothing. The
// check and the delete run in one transaction, so a concurrent create cannot
// interleave and a repeat delete still misses; the removal is committed to
// disk before the call returns.
func (s *Store) DeleteSession(deviceID, sessionID string) error {
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()

	var owner string
	err = tx.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&owner)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return ErrSessionNotFound
	case err != nil:
		return err
	}
	if owner != deviceID {
		return ErrSessionNotFound
	}

	if _, err := tx.Exec(
		`DELETE FROM sessions WHERE id = ? AND device_id = ?`,
		sessionID, deviceID,
	); err != nil {
		return err
	}
	return tx.Commit()
}

// DeleteDeviceTx deregisters deviceID and removes every record it owns, all
// inside the caller's serialized transaction:
//
//   - the device's sessions are hard-deleted, so their session-scoped reads
//     and subscriptions miss from then on;
//   - every attachment it created is removed together with its chunks, its
//     sealed/unfinished state and the access rows other devices held on it;
//   - the read grants the device itself held on other devices' attachments
//     are withdrawn;
//   - the device row is removed last (every child row goes first).
//
// Digest-addressed content is shared across attachments and is reclaimed only
// when no completed attachment still references a digest — exactly the rule
// of a single attachment delete — so another device's attachment with the same
// digest keeps its bytes and one deregistration by itself never reclaims
// shared content. The document permission ledger lives in the authz package
// and clears its own rows against the same transaction through
// DeleteDevicePermissionsTx.
//
// An unknown (never registered or already deregistered) device yields
// ErrDeviceNotFound and writes nothing. Because the whole judgment runs in one
// immediate transaction on the single shared connection, concurrent
// deregistrations of the same device commit at most once and any concurrent
// chunk upload or finish either committed entirely before it or is rejected
// entirely afterward — no half-written record survives.
func DeleteDeviceTx(q DBTX, deviceID string) error {
	exists, err := DeviceExistsTx(q, deviceID)
	if err != nil {
		return err
	}
	if !exists {
		return ErrDeviceNotFound
	}

	// Remember the digests of the device's completed attachments before their
	// rows vanish: each is a candidate for content reclamation once every
	// owned attachment is gone. DISTINCT because several of the device's
	// attachments may share the same digest-addressed content.
	rows, err := q.Query(
		`SELECT DISTINCT sha256 FROM attachments WHERE device_id = ? AND complete = 1`,
		deviceID,
	)
	if err != nil {
		return err
	}
	var digests []string
	for rows.Next() {
		var digest string
		if err := rows.Scan(&digest); err != nil {
			_ = rows.Close()
			return err
		}
		digests = append(digests, digest)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	if err := rows.Close(); err != nil {
		return err
	}

	// Withdraw the read grants this device held on other devices'
	// attachments (rows naming it as the grantee), then remove the access
	// rosters of the attachments it created before the attachment rows those
	// rosters reference are deleted.
	if _, err := q.Exec(
		`DELETE FROM attachment_access WHERE device_id = ?`, deviceID,
	); err != nil {
		return err
	}
	if _, err := q.Exec(
		`DELETE FROM attachment_access
		 WHERE attachment_id IN (SELECT id FROM attachments WHERE device_id = ?)`,
		deviceID,
	); err != nil {
		return err
	}
	if _, err := q.Exec(
		`DELETE FROM attachment_chunks
		 WHERE attachment_id IN (SELECT id FROM attachments WHERE device_id = ?)`,
		deviceID,
	); err != nil {
		return err
	}
	if _, err := q.Exec(
		`DELETE FROM attachments WHERE device_id = ?`, deviceID,
	); err != nil {
		return err
	}

	// Reclaim each digest-addressed content only when no surviving completed
	// attachment — owned by another device, or by the deregistered device in
	// an impossible re-read — still references it.
	for _, digest := range digests {
		var stillReferenced bool
		if err := q.QueryRow(
			`SELECT EXISTS(SELECT 1 FROM attachments WHERE sha256 = ? AND complete = 1)`,
			digest,
		).Scan(&stillReferenced); err != nil {
			return err
		}
		if !stillReferenced {
			if _, err := q.Exec(
				`DELETE FROM attachment_contents WHERE sha256 = ?`, digest,
			); err != nil {
				return err
			}
		}
	}

	if _, err := q.Exec(
		`DELETE FROM sessions WHERE device_id = ?`, deviceID,
	); err != nil {
		return err
	}
	if _, err := q.Exec(
		`DELETE FROM devices WHERE id = ?`, deviceID,
	); err != nil {
		return err
	}
	return nil
}

// SessionExists reports whether a live session with sessionID exists.
// Ownership is intentionally not part of this check: session-scoped reads only
// require that the session currently exists.
func (s *Store) SessionExists(sessionID string) (bool, error) {
	var exists bool
	if err := s.db.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM sessions WHERE id = ?)`, sessionID,
	).Scan(&exists); err != nil {
		return false, err
	}
	return exists, nil
}

// SessionDevice returns the id of the device that owns the live session
// sessionID. A session that was never created or was deleted yields
// ErrSessionNotFound.
func (s *Store) SessionDevice(sessionID string) (string, error) {
	var deviceID string
	err := s.db.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&deviceID)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return "", ErrSessionNotFound
	case err != nil:
		return "", err
	default:
		return deviceID, nil
	}
}

// JSONEqual reports whether two payloads are equal after JSON decoding, so
// 1 and 1.0, or {"a":1,"b":2} and {"b":2,"a":1}, compare equal. It is shared
// verbatim by the change event and CRDT services' idempotency judgments.
func JSONEqual(a, b json.RawMessage) bool {
	var va, vb any
	if err := json.Unmarshal(a, &va); err != nil {
		return false
	}
	if err := json.Unmarshal(b, &vb); err != nil {
		return false
	}
	return deepEqual(va, vb)
}

func deepEqual(a, b any) bool {
	switch av := a.(type) {
	case nil:
		return b == nil
	case bool:
		bv, ok := b.(bool)
		return ok && av == bv
	case string:
		bv, ok := b.(string)
		return ok && av == bv
	case float64:
		bv, ok := b.(float64)
		return ok && av == bv
	case []any:
		bv, ok := b.([]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for i := range av {
			if !deepEqual(av[i], bv[i]) {
				return false
			}
		}
		return true
	case map[string]any:
		bv, ok := b.(map[string]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for k, v := range av {
			w, exists := bv[k]
			if !exists || !deepEqual(v, w) {
				return false
			}
		}
		return true
	default:
		return false
	}
}

// Package events is the change event service: the durable per-document change
// log together with everything written on top of it.
//
// Within a document every change has a client-supplied id. New ids receive a
// monotonically increasing cursor; re-posting an existing id is idempotent
// only when the deviceId and decoded JSON payload match, otherwise it is a
// conflict. Valid batches commit atomically in one serialized transaction, so
// cursors never repeat and no record is partially written, even under
// concurrent writers. Ordinary posts, offline replays, merges and snapshot
// restores all allocate from the same per-document contiguous cursor space.
//
// A document may also carry snapshots: caller-supplied JSON states pinned to
// existing change cursors. Snapshots are write-once per cursor — a matching
// re-post is idempotent, a differing one a conflict — and live apart from the
// change log. A restore appends an ordinary change whose payload is a
// snapshot's state, recording its provenance so a repeated restore after a
// restart keeps the same idempotency/conflict decisions.
//
// Reads page by cursor in ascending order. The session view and the document
// view are the same read; the HTTP layer adds the session/permission checks.
// Long polling and push subscriptions are in-memory observers of commits:
// they register before the confirming read, hold no durable state, and are
// woken only after a change-bearing transaction has committed.
//
// The service owns only its own tables. The registration and permission
// layers are reached through its Gate interface, so a replay or merge never
// reaches into another service's storage.
package events

import (
	"encoding/json"
	"errors"
	"fmt"
)

// ErrStoreClosing reports that the service is shutting down and parked long
// polls have been woken so they can return without writing anything. The
// caller maps it to 503.
var ErrStoreClosing = errors.New("store is closing")

// Change is one element of an inbound batch or one row of a listing.
type Change struct {
	ID       string          // client-supplied change id, unique per document
	DeviceID string          // originating device
	Payload  json.RawMessage // decoded JSON value, stored verbatim
}

// Result reports the outcome for one element of an accepted batch.
type Result struct {
	ID      string `json:"id"`
	Created bool   `json:"created"`
	Cursor  int64  `json:"cursor"`
}

// ListedChange is one row in a ListChanges response.
type ListedChange struct {
	ID       string          `json:"id"`
	DeviceID string          `json:"deviceId"`
	Payload  json.RawMessage `json:"payload"`
	Cursor   int64           `json:"cursor"`
}

// MergeResult reports the outcome of an accepted MergeChange. Outcome is one
// of "idempotent", "applied" or "merged".
type MergeResult struct {
	ID      string  `json:"id"`
	Outcome string  `json:"outcome"`
	Cursor  int64   `json:"cursor"`
	Result  *Result `json:"result,omitempty"`
}

// ErrConflict reports that a batch references an existing change id with a
// different deviceId or payload. The whole batch is rejected.
type ErrConflict struct {
	ID string
}

func (e *ErrConflict) Error() string {
	return fmt.Sprintf("conflicting change %q for document", e.ID)
}

// ErrStaleCursor reports that a merge targets a base cursor for an unknown
// document, or a base cursor greater than the document's current cursor. The
// caller maps it to 400; nothing is written.
var ErrStaleCursor = errors.New("baseCursor is unknown or ahead of the current cursor")

// ErrSnapshotBase reports that a snapshot targets an unknown document or a
// cursor that is not an existing change cursor of the document. The caller
// maps it to 400; nothing is written.
var ErrSnapshotBase = errors.New("snapshot cursor is not an existing cursor of the document")

// ErrCompactedBase reports that a merge targets a base cursor below the
// document's compaction boundary: the changes it would be checked against
// have left the online log, so the conflict check cannot be completed. The
// caller maps it to 400; nothing is written.
var ErrCompactedBase = errors.New("baseCursor is below the compaction boundary")

// ErrSnapshotNotFound reports that no snapshot exists for the document and
// cursor. The caller maps it to 404.
var ErrSnapshotNotFound = errors.New("snapshot not found")

// ErrSnapshotConflict reports that a snapshot already exists for the document
// and cursor with a different state. The stored snapshot is left unchanged.
type ErrSnapshotConflict struct {
	Cursor int64
}

func (e *ErrSnapshotConflict) Error() string {
	return fmt.Sprintf("conflicting snapshot for cursor %d", e.Cursor)
}

// ErrRestoreConflict reports that a restore references a change id that is
// already taken by an ordinary change, or by a prior restore whose deviceId,
// snapshot cursor or source state differs. Nothing is written; the caller maps
// it to 409.
type ErrRestoreConflict struct {
	ID string
}

func (e *ErrRestoreConflict) Error() string {
	return fmt.Sprintf("change id %q conflicts with the change log", e.ID)
}

// ExportedSnapshot is one row of an ExportSnapshots result.
type ExportedSnapshot struct {
	Cursor int64           `json:"cursor"`
	State  json.RawMessage `json:"state"`
}

// RestoreResult reports the outcome of an accepted RestoreSnapshot.
type RestoreResult struct {
	ID           string `json:"id"`
	Created      bool   `json:"created"`
	Cursor       int64  `json:"cursor"`
	RestoredFrom int64  `json:"restoredFrom"`
}

// schema is created when the service is constructed. Table and index shapes
// are unchanged from the pre-refactor layout, so data already on disk stays
// readable.
const schema = `
CREATE TABLE IF NOT EXISTS changes (
	document_id TEXT NOT NULL,
	cursor      INTEGER NOT NULL,
	id          TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	payload     BLOB NOT NULL,
	PRIMARY KEY (document_id, id)
);
CREATE UNIQUE INDEX IF NOT EXISTS changes_doc_cursor_idx
	ON changes(document_id, cursor);
CREATE TABLE IF NOT EXISTS snapshots (
	document_id TEXT NOT NULL,
	cursor      INTEGER NOT NULL,
	state       BLOB NOT NULL,
	PRIMARY KEY (document_id, cursor)
);
CREATE TABLE IF NOT EXISTS restores (
	document_id     TEXT NOT NULL,
	change_id       TEXT NOT NULL,
	device_id       TEXT NOT NULL,
	snapshot_cursor INTEGER NOT NULL,
	change_cursor   INTEGER NOT NULL,
	state           BLOB NOT NULL,
	PRIMARY KEY (document_id, change_id)
);
CREATE UNIQUE INDEX IF NOT EXISTS restores_doc_cursor_idx
	ON restores(document_id, change_cursor);
CREATE TABLE IF NOT EXISTS change_boundaries (
	document_id TEXT NOT NULL PRIMARY KEY,
	boundary    INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS change_identities (
	document_id   TEXT NOT NULL,
	id            TEXT NOT NULL,
	device_id     TEXT NOT NULL,
	digest        BLOB NOT NULL,
	cursor        INTEGER NOT NULL,
	restored_from INTEGER,
	PRIMARY KEY (document_id, id)
);
`

package server

import (
	"errors"
	"net/http"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// compactChangesRequest is the body of POST .../changes/compact: the same
// device field the CRDT compaction endpoint carries.
type compactChangesRequest struct {
	DeviceID string `json:"deviceId"`
}

// compactChangesResponse is the success body of POST .../changes/compact. The
// struct field order fixes the key order (boundary, then removed), and the
// shared JSON writer emits it as one compact line with a trailing newline.
type compactChangesResponse struct {
	Boundary int64 `json:"boundary"`
	Removed  int64 `json:"removed"`
}

// handleCompactChanges moves the document's changes at or below the
// compaction boundary — the greatest cursor with a saved snapshot, zero when
// the document has none — out of the online change log.
//
// The request contract matches the CRDT compaction endpoint: strict
// application/json, exactly one JSON value, no trailing content and a
// non-empty deviceId — any violation is a 400 JSON error with zero writes.
// The gate then applies in the submission's order: an unregistered device is
// a 404 and a device whose permission for the document was revoked is a 403;
// neither writes anything. A snapshot-less or unknown document compacts
// successfully with boundary 0 and nothing removed.
//
// On success the answer is 200 with one compact JSON line naming the boundary
// and the number of changes this call removed. Compaction is idempotent — a
// repeat reports the same boundary and zero removed — and is not itself a
// change: it allocates no cursor, writes no change record and wakes no waiter
// or subscriber.
func handleCompactChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	var req compactChangesRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}

	boundary, removed, err := s.CompactChanges(documentID, req.DeviceID)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		default:
			writeError(w, http.StatusInternalServerError, "failed to compact changes")
		}
		return
	}

	writeJSON(w, http.StatusOK, compactChangesResponse{Boundary: boundary, Removed: removed})
}

package server

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"testing"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
)

// The whole attachment path over the public HTTP surface: register a device,
// create the upload, push chunks out of order, retry them after a reconnect,
// seal, observe content dedup across devices and the seal's immutability.
func TestAttachmentLifecycleEndToEndContract(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	registerDevice(t, h, "dev-2")
	content := []byte("hello world") // 11 bytes, chunks of 4: [hell][o wo][rld]

	// Create: first attempt creates, an identical retry is idempotent.
	w, body := createAttachment(t, h, "dev-1", "att-1", 11, 4, sha256Hex(content))
	if w.Code != http.StatusOK || body["created"] != true {
		t.Fatalf("create = %d %v body=%s", w.Code, body, w.Body.String())
	}
	w, body = createAttachment(t, h, "dev-1", "att-1", 11, 4, sha256Hex(content))
	if w.Code != http.StatusOK || body["created"] != false {
		t.Fatalf("create retry = %d %v body=%s", w.Code, body, w.Body.String())
	}

	// Chunks arrive out of order; each first store reports created=true.
	for _, c := range []struct {
		index int64
		data  string
	}{
		{2, "rld"},
		{0, "hell"},
		{1, "o wo"},
	} {
		w, body = putChunk(t, h, "dev-1", "att-1", c.index, []byte(c.data))
		if w.Code != http.StatusOK || body["created"] != true || body["index"] != float64(c.index) {
			t.Fatalf("chunk %d = %d %v body=%s", c.index, w.Code, body, w.Body.String())
		}
	}
	// A reconnect retries the last chunk: idempotent, created=false.
	w, body = putChunk(t, h, "dev-1", "att-1", 1, []byte("o wo"))
	if w.Code != http.StatusOK || body["created"] != false {
		t.Fatalf("reconnect retry = %d %v body=%s", w.Code, body, w.Body.String())
	}

	// Seal: the recorded result carries the declared size and digest.
	w, body = completeAttachment(t, h, "dev-1", "att-1")
	if w.Code != http.StatusOK || body["complete"] != true || body["reused"] != false ||
		body["size"] != float64(11) || body["sha256"] != sha256Hex(content) {
		t.Fatalf("complete = %d %v body=%s", w.Code, body, w.Body.String())
	}

	// A second device uploading the same content reuses the stored bytes.
	mustCreateAttachment(t, h, "dev-2", "att-2", content, 4)
	putChunk(t, h, "dev-2", "att-2", 0, []byte("hell"))
	putChunk(t, h, "dev-2", "att-2", 1, []byte("o wo"))
	putChunk(t, h, "dev-2", "att-2", 2, []byte("rld"))
	w, body = completeAttachment(t, h, "dev-2", "att-2")
	if w.Code != http.StatusOK || body["reused"] != true || body["size"] != float64(11) {
		t.Fatalf("dedup complete = %d %v body=%s", w.Code, body, w.Body.String())
	}

	// The seal is immutable: even a byte-identical chunk write is a 409.
	w, _ = putChunk(t, h, "dev-1", "att-1", 0, []byte("hell"))
	if w.Code != http.StatusConflict {
		t.Fatalf("write after seal = %d, want 409", w.Code)
	}
	assertJSONError(t, w)
}

// Access and request-shape matrix for the attachment read/write endpoints:
// unknown ids are 404, non-creators are 403, illegal indices and empty
// identifiers are 400 — every one a JSON error that leaks no content.
func TestAttachmentAccessAndShapeContract(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	registerDevice(t, h, "dev-2")
	content := []byte("hello world")
	mustCreateAttachment(t, h, "dev-1", "att-1", content, 4)
	putChunk(t, h, "dev-1", "att-1", 0, []byte("hell"))

	// Unknown attachment metadata read: 404 JSON, no content.
	r := httptest.NewRequest(http.MethodGet, "/v1/devices/dev-1/attachments/nope", nil)
	w := serveRecorder(h, r)
	if w.Code != http.StatusNotFound {
		t.Fatalf("get unknown meta = %d, want 404", w.Code)
	}
	assertJSONError(t, w)

	// Non-creator metadata read: 403 JSON, no metadata leaked.
	r = httptest.NewRequest(http.MethodGet, "/v1/devices/dev-2/attachments/att-1", nil)
	w = serveRecorder(h, r)
	if w.Code != http.StatusForbidden {
		t.Fatalf("get non-creator meta = %d, want 403", w.Code)
	}
	assertJSONError(t, w)
	if strings.Contains(w.Body.String(), "hello") || strings.Contains(w.Body.String(), sha256Hex(content)) {
		t.Fatalf("403 body leaks content: %s", w.Body.String())
	}

	// Illegal chunk indices on the write path: 400 JSON.
	for _, index := range []string{"-1", "x", "1.5"} {
		r = httptest.NewRequest(http.MethodPut,
			"/v1/devices/dev-1/attachments/att-1/chunks/"+index, strings.NewReader("hell"))
		r.Header.Set("Content-Type", "application/octet-stream")
		w = serveRecorder(h, r)
		if w.Code != http.StatusBadRequest {
			t.Fatalf("put chunk index %q = %d, want 400", index, w.Code)
		}
		assertJSONError(t, w)
	}

	// Empty identifiers and trailing slashes on the chunk paths: 400 JSON.
	for _, path := range []string{
		"/v1/devices//attachments/att-1/chunks/0",
		"/v1/devices/dev-1/attachments//chunks/0",
		"/v1/devices/dev-1/attachments/att-1/chunks/",
		"/v1/devices/dev-1/attachments/",
	} {
		r = httptest.NewRequest(http.MethodPut, path, strings.NewReader("hell"))
		r.Header.Set("Content-Type", "application/octet-stream")
		w = serveRecorder(h, r)
		if w.Code != http.StatusBadRequest {
			t.Fatalf("PUT %s = %d, want 400", path, w.Code)
		}
		assertJSONError(t, w)
	}

	// None of the rejections stored anything: only chunk 0 was ever received.
	r = httptest.NewRequest(http.MethodGet, "/v1/devices/dev-1/attachments/att-1", nil)
	w = serveRecorder(h, r)
	if !strings.Contains(w.Body.String(), `"receivedChunks":[0]`) {
		t.Fatalf("receivedChunks after rejections = %s", w.Body.String())
	}
}

// Finishing an upload that has no chunks at all is a 409 and the upload stays
// resumable: the chunks can still arrive afterwards and the finish succeeds.
func TestAttachmentCompleteWithNoChunksIs409AndResumable(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	content := []byte("data")
	mustCreateAttachment(t, h, "dev-1", "att-1", content, 2)

	w, _ := completeAttachment(t, h, "dev-1", "att-1")
	if w.Code != http.StatusConflict {
		t.Fatalf("complete with no chunks = %d, want 409", w.Code)
	}
	assertJSONError(t, w)

	// The failed finish sealed nothing: chunks are still accepted.
	w, body := putChunk(t, h, "dev-1", "att-1", 0, []byte("da"))
	if w.Code != http.StatusOK || body["created"] != true {
		t.Fatalf("chunk after 409 = %d %v body=%s", w.Code, body, w.Body.String())
	}
	putChunk(t, h, "dev-1", "att-1", 1, []byte("ta"))
	w, body = completeAttachment(t, h, "dev-1", "att-1")
	if w.Code != http.StatusOK || body["complete"] != true || body["size"] != float64(4) {
		t.Fatalf("complete after resume = %d %v body=%s", w.Code, body, w.Body.String())
	}
}

// A digest mismatch is a 422 that leaves the upload incomplete, and that
// judgment survives a restart: the same finish is still a 422, the metadata
// still reports incomplete and the stored chunks are still readable.
func TestAttachmentDigestMismatchPersistsAcrossRestart(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "sync.db")
	open := func(t *testing.T) (http.Handler, *app.App) {
		t.Helper()
		s, err := app.Open(dbPath)
		if err != nil {
			t.Fatal(err)
		}
		return NewHandler(s), s
	}

	h, s := open(t)
	registerDevice(t, h, "dev-1")
	// The declared digest belongs to other content than what will arrive.
	w, body := createAttachment(t, h, "dev-1", "att-1", 4, 2, sha256Hex([]byte("xyz!")))
	if w.Code != http.StatusOK || body["created"] != true {
		t.Fatalf("create = %d %v", w.Code, body)
	}
	putChunk(t, h, "dev-1", "att-1", 0, []byte("da"))
	putChunk(t, h, "dev-1", "att-1", 1, []byte("ta"))

	assertMismatch := func(t *testing.T, h http.Handler) {
		t.Helper()
		w, _ := completeAttachment(t, h, "dev-1", "att-1")
		if w.Code != http.StatusUnprocessableEntity {
			t.Fatalf("digest mismatch = %d, want 422", w.Code)
		}
		assertJSONError(t, w)
		r := httptest.NewRequest(http.MethodGet, "/v1/devices/dev-1/attachments/att-1", nil)
		w = serveRecorder(h, r)
		if !strings.Contains(w.Body.String(), `"complete":false`) ||
			!strings.Contains(w.Body.String(), `"receivedChunks":[0,1]`) {
			t.Fatalf("meta after 422 = %s", w.Body.String())
		}
		r = httptest.NewRequest(http.MethodGet, "/v1/devices/dev-1/attachments/att-1/chunks/1", nil)
		w = serveRecorder(h, r)
		if w.Code != http.StatusOK || w.Body.String() != "ta" {
			t.Fatalf("chunk after 422 = %d %q", w.Code, w.Body.String())
		}
	}
	assertMismatch(t, h)
	_ = s.Close()

	h, s = open(t)
	defer func() { _ = s.Close() }()
	assertMismatch(t, h)
}

// The same digest at a different size must never be silently reused: an
// upload that declares the digest of an already-finished attachment but a
// different size can never assemble matching bytes, so its finish is rejected
// (the assembled content does not hash to the declared digest: 422) and the
// upload stays unsealed instead of being completed against foreign bytes.
func TestAttachmentSameDigestDifferentSizeNeverReused(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	content := []byte("hello world")
	mustCreateAttachment(t, h, "dev-1", "att-1", content, 4)
	putChunk(t, h, "dev-1", "att-1", 0, []byte("hell"))
	putChunk(t, h, "dev-1", "att-1", 1, []byte("o wo"))
	putChunk(t, h, "dev-1", "att-1", 2, []byte("rld"))
	w, body := completeAttachment(t, h, "dev-1", "att-1")
	if w.Code != http.StatusOK || body["reused"] != false {
		t.Fatalf("first complete = %d %v", w.Code, body)
	}

	// A second upload declares the same digest but a different size. Its
	// finish must not be answered with the stored content: the assembled
	// bytes cannot match the declared digest, so the finish is a 422 and the
	// upload stays resumable rather than being sealed against foreign bytes.
	w, body = createAttachment(t, h, "dev-1", "att-2", 6, 6, sha256Hex(content))
	if w.Code != http.StatusOK || body["created"] != true {
		t.Fatalf("create different-size = %d %v", w.Code, body)
	}
	putChunk(t, h, "dev-1", "att-2", 0, []byte("hello "))
	w, _ = completeAttachment(t, h, "dev-1", "att-2")
	if w.Code != http.StatusUnprocessableEntity {
		t.Fatalf("same digest different size = %d, want 422 (never a silent reuse)", w.Code)
	}
	assertJSONError(t, w)
	r := httptest.NewRequest(http.MethodGet, "/v1/devices/dev-1/attachments/att-2", nil)
	w = serveRecorder(h, r)
	if !strings.Contains(w.Body.String(), `"complete":false`) {
		t.Fatalf("different-size upload sealed: %s", w.Body.String())
	}
}

// After a restart the create/chunk idempotency and the 403/404 access
// judgments are unchanged.
func TestAttachmentAccessJudgmentsSurviveRestart(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "sync.db")
	open := func(t *testing.T) (http.Handler, *app.App) {
		t.Helper()
		s, err := app.Open(dbPath)
		if err != nil {
			t.Fatal(err)
		}
		return NewHandler(s), s
	}

	h, s := open(t)
	registerDevice(t, h, "dev-1")
	registerDevice(t, h, "dev-2")
	content := []byte("hello world")
	mustCreateAttachment(t, h, "dev-1", "att-1", content, 4)
	putChunk(t, h, "dev-1", "att-1", 0, []byte("hell"))
	_ = s.Close()

	h, s = open(t)
	defer func() { _ = s.Close() }()

	// The create retry is still idempotent; a metadata-different create by the
	// same device and any create by another device are still 409.
	w, body := createAttachment(t, h, "dev-1", "att-1", 11, 4, sha256Hex(content))
	if w.Code != http.StatusOK || body["created"] != false {
		t.Fatalf("create retry after restart = %d %v", w.Code, body)
	}
	w, _ = createAttachment(t, h, "dev-1", "att-1", 12, 4, sha256Hex(content))
	if w.Code != http.StatusConflict {
		t.Fatalf("different metadata after restart = %d, want 409", w.Code)
	}
	w, _ = createAttachment(t, h, "dev-2", "att-1", 11, 4, sha256Hex(content))
	if w.Code != http.StatusConflict {
		t.Fatalf("cross-device create after restart = %d, want 409", w.Code)
	}
	// Non-creator access is still 403, unknown ids still 404.
	w, _ = putChunk(t, h, "dev-2", "att-1", 1, []byte("o wo"))
	if w.Code != http.StatusForbidden {
		t.Fatalf("non-creator chunk after restart = %d, want 403", w.Code)
	}
	w, _ = completeAttachment(t, h, "dev-1", "nope")
	if w.Code != http.StatusNotFound {
		t.Fatalf("unknown complete after restart = %d, want 404", w.Code)
	}
	// The interrupted upload resumes and seals.
	putChunk(t, h, "dev-1", "att-1", 1, []byte("o wo"))
	putChunk(t, h, "dev-1", "att-1", 2, []byte("rld"))
	w, body = completeAttachment(t, h, "dev-1", "att-1")
	if w.Code != http.StatusOK || body["complete"] != true {
		t.Fatalf("complete after restart = %d %v", w.Code, body)
	}
	// Chunks read back in order reassemble the original content.
	var got strings.Builder
	for i := int64(0); i < 3; i++ {
		r := httptest.NewRequest(http.MethodGet, fmt.Sprintf("/v1/devices/dev-1/attachments/att-1/chunks/%d", i), nil)
		w = serveRecorder(h, r)
		if w.Code != http.StatusOK {
			t.Fatalf("chunk %d after restart = %d", i, w.Code)
		}
		got.WriteString(w.Body.String())
	}
	if got.String() != string(content) {
		t.Fatalf("reassembled content = %q, want %q", got.String(), content)
	}
}

package server

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"testing"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
)

func sha256Hex(data []byte) string {
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:])
}

// createAttachment posts a create request and returns the recorder.
func createAttachment(t *testing.T, h http.Handler, deviceID, attachmentID string, total, chunk int64, digest string) (*httptest.ResponseRecorder, map[string]any) {
	t.Helper()
	return postJSON(t, h, "/v1/devices/"+deviceID+"/attachments", map[string]any{
		"attachmentId": attachmentID,
		"totalBytes":   total,
		"chunkSize":    chunk,
		"sha256":       digest,
	})
}

// mustCreateAttachment registers a fresh attachment whose digest matches
// content, failing the test on any error.
func mustCreateAttachment(t *testing.T, h http.Handler, deviceID, attachmentID string, content []byte, chunkSize int64) {
	t.Helper()
	w, body := createAttachment(t, h, deviceID, attachmentID, int64(len(content)), chunkSize, sha256Hex(content))
	if w.Code != http.StatusOK || body["created"] != true {
		t.Fatalf("create attachment = %d %v body=%s", w.Code, body, w.Body.String())
	}
}

func putChunk(t *testing.T, h http.Handler, deviceID, attachmentID string, index int64, data []byte) (*httptest.ResponseRecorder, map[string]any) {
	t.Helper()
	r := httptest.NewRequest(http.MethodPut,
		fmt.Sprintf("/v1/devices/%s/attachments/%s/chunks/%d", deviceID, attachmentID, index),
		strings.NewReader(string(data)))
	r.Header.Set("Content-Type", "application/octet-stream")
	w := httptest.NewRecorder()
	h.ServeHTTP(w, r)
	var body map[string]any
	if w.Body.Len() > 0 {
		_ = json.Unmarshal(w.Body.Bytes(), &body)
	}
	return w, body
}

func completeAttachment(t *testing.T, h http.Handler, deviceID, attachmentID string) (*httptest.ResponseRecorder, map[string]any) {
	t.Helper()
	r := httptest.NewRequest(http.MethodPost,
		"/v1/devices/"+deviceID+"/attachments/"+attachmentID+"/complete", nil)
	w := httptest.NewRecorder()
	h.ServeHTTP(w, r)
	var body map[string]any
	if w.Body.Len() > 0 {
		_ = json.Unmarshal(w.Body.Bytes(), &body)
	}
	return w, body
}

func TestCreateAttachmentHTTP(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")

	digest := sha256Hex([]byte("hello world"))
	w, body := createAttachment(t, h, "dev-1", "att-1", 11, 4, digest)
	if w.Code != http.StatusOK || body["created"] != true || body["attachmentId"] != "att-1" {
		t.Fatalf("create = %d %v body=%s", w.Code, body, w.Body.String())
	}

	// Identical retry by the same device is idempotent.
	w, body = createAttachment(t, h, "dev-1", "att-1", 11, 4, digest)
	if w.Code != http.StatusOK || body["created"] != false {
		t.Fatalf("retry = %d %v body=%s", w.Code, body, w.Body.String())
	}
}

func TestCreateAttachmentRejectsBadInput(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	digest := sha256Hex([]byte("x"))

	cases := []struct {
		name        string
		contentType string
		body        string
	}{
		{"wrong content type", "text/plain", `{"attachmentId":"a","totalBytes":1,"chunkSize":1,"sha256":"` + digest + `"}`},
		{"malformed json", "application/json", `{`},
		{"trailing content", "application/json", `{"attachmentId":"a","totalBytes":1,"chunkSize":1,"sha256":"` + digest + `"}x`},
		{"missing attachmentId", "application/json", `{"totalBytes":1,"chunkSize":1,"sha256":"` + digest + `"}`},
		{"empty attachmentId", "application/json", `{"attachmentId":"","totalBytes":1,"chunkSize":1,"sha256":"` + digest + `"}`},
		{"numeric attachmentId", "application/json", `{"attachmentId":1,"totalBytes":1,"chunkSize":1,"sha256":"` + digest + `"}`},
		{"missing totalBytes", "application/json", `{"attachmentId":"a","chunkSize":1,"sha256":"` + digest + `"}`},
		{"zero totalBytes", "application/json", `{"attachmentId":"a","totalBytes":0,"chunkSize":1,"sha256":"` + digest + `"}`},
		{"negative totalBytes", "application/json", `{"attachmentId":"a","totalBytes":-3,"chunkSize":1,"sha256":"` + digest + `"}`},
		{"fractional totalBytes", "application/json", `{"attachmentId":"a","totalBytes":1.5,"chunkSize":1,"sha256":"` + digest + `"}`},
		{"string totalBytes", "application/json", `{"attachmentId":"a","totalBytes":"3","chunkSize":1,"sha256":"` + digest + `"}`},
		{"missing chunkSize", "application/json", `{"attachmentId":"a","totalBytes":1,"sha256":"` + digest + `"}`},
		{"zero chunkSize", "application/json", `{"attachmentId":"a","totalBytes":1,"chunkSize":0,"sha256":"` + digest + `"}`},
		{"missing sha256", "application/json", `{"attachmentId":"a","totalBytes":1,"chunkSize":1}`},
		{"short sha256", "application/json", `{"attachmentId":"a","totalBytes":1,"chunkSize":1,"sha256":"abc"}`},
		{"uppercase sha256", "application/json", `{"attachmentId":"a","totalBytes":1,"chunkSize":1,"sha256":"` + strings.ToUpper(digest) + `"}`},
		{"non-hex sha256", "application/json", `{"attachmentId":"a","totalBytes":1,"chunkSize":1,"sha256":"` + strings.Repeat("g", 64) + `"}`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			r := newJSONRequest(http.MethodPost, "/v1/devices/dev-1/attachments", tc.body, tc.contentType)
			w := serveRecorder(h, r)
			if w.Code != http.StatusBadRequest {
				t.Fatalf("status = %d, want 400 body=%s", w.Code, w.Body.String())
			}
			assertJSONError(t, w)
		})
	}

	// Zero writes: none of the rejected creates left anything behind.
	r := httptest.NewRequest(http.MethodGet, "/v1/devices/dev-1/attachments/a", nil)
	w := serveRecorder(h, r)
	if w.Code != http.StatusNotFound {
		t.Fatalf("GET after rejected creates = %d, want 404", w.Code)
	}
}

func TestCreateAttachmentDeviceAndConflict(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	registerDevice(t, h, "dev-2")
	digest := sha256Hex([]byte("data"))

	// Unregistered device: 404.
	w, _ := createAttachment(t, h, "ghost", "att-1", 4, 2, digest)
	if w.Code != http.StatusNotFound {
		t.Fatalf("unknown device = %d, want 404", w.Code)
	}

	mustCreateAttachment(t, h, "dev-1", "att-1", []byte("data"), 2)

	// Same id, other device, identical metadata: 409, original unchanged.
	w, _ = createAttachment(t, h, "dev-2", "att-1", 4, 2, digest)
	if w.Code != http.StatusConflict {
		t.Fatalf("cross-device create = %d, want 409", w.Code)
	}
	assertJSONError(t, w)

	// Same device, different metadata: 409.
	w, _ = createAttachment(t, h, "dev-1", "att-1", 8, 2, digest)
	if w.Code != http.StatusConflict {
		t.Fatalf("different metadata = %d, want 409", w.Code)
	}

	// The original record is intact.
	r := httptest.NewRequest(http.MethodGet, "/v1/devices/dev-1/attachments/att-1", nil)
	w = serveRecorder(h, r)
	var body map[string]any
	_ = json.Unmarshal(w.Body.Bytes(), &body)
	if w.Code != http.StatusOK || body["totalBytes"] != float64(4) || body["chunkSize"] != float64(2) {
		t.Fatalf("original record changed: %d %v", w.Code, body)
	}
}

func TestChunkUploadHTTP(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	registerDevice(t, h, "dev-2")
	content := []byte("hello world") // 11 bytes, chunks of 4: [hell][o wo][rld]
	mustCreateAttachment(t, h, "dev-1", "att-1", content, 4)

	// Out-of-order uploads are accepted.
	w, body := putChunk(t, h, "dev-1", "att-1", 1, []byte("o wo"))
	if w.Code != http.StatusOK || body["created"] != true {
		t.Fatalf("chunk 1 = %d %v body=%s", w.Code, body, w.Body.String())
	}
	w, body = putChunk(t, h, "dev-1", "att-1", 0, []byte("hell"))
	if w.Code != http.StatusOK || body["created"] != true {
		t.Fatalf("chunk 0 = %d %v body=%s", w.Code, body, w.Body.String())
	}

	// Re-submitting identical bytes is idempotent.
	w, body = putChunk(t, h, "dev-1", "att-1", 0, []byte("hell"))
	if w.Code != http.StatusOK || body["created"] != false {
		t.Fatalf("idempotent chunk = %d %v body=%s", w.Code, body, w.Body.String())
	}

	// Different bytes at the same index: 409, first content kept.
	w, _ = putChunk(t, h, "dev-1", "att-1", 0, []byte("HELL"))
	if w.Code != http.StatusConflict {
		t.Fatalf("conflicting chunk = %d, want 409", w.Code)
	}
	assertJSONError(t, w)
	r := httptest.NewRequest(http.MethodGet, "/v1/devices/dev-1/attachments/att-1/chunks/0", nil)
	w = serveRecorder(h, r)
	if w.Code != http.StatusOK || w.Body.String() != "hell" {
		t.Fatalf("chunk 0 after conflict = %d %q, want first content", w.Code, w.Body.String())
	}

	// Wrong content type.
	r = httptest.NewRequest(http.MethodPut, "/v1/devices/dev-1/attachments/att-1/chunks/2", strings.NewReader("rld"))
	r.Header.Set("Content-Type", "application/json")
	w = serveRecorder(h, r)
	if w.Code != http.StatusBadRequest {
		t.Fatalf("json content type = %d, want 400", w.Code)
	}
	assertJSONError(t, w)

	// Index out of range.
	w, _ = putChunk(t, h, "dev-1", "att-1", 3, []byte("xxxx"))
	if w.Code != http.StatusBadRequest {
		t.Fatalf("index 3 = %d, want 400", w.Code)
	}

	// Non-final chunk with the wrong length.
	w, _ = putChunk(t, h, "dev-1", "att-1", 1, []byte("short"))
	if w.Code != http.StatusBadRequest {
		t.Fatalf("short non-final chunk = %d, want 400", w.Code)
	}

	// Final chunk beyond the declared total (4 bytes would reach 12 > 11).
	w, _ = putChunk(t, h, "dev-1", "att-1", 2, []byte("rld!"))
	if w.Code != http.StatusBadRequest {
		t.Fatalf("oversized final chunk = %d, want 400", w.Code)
	}

	// Unknown attachment: 404. Other device: 403.
	w, _ = putChunk(t, h, "dev-1", "nope", 0, []byte("hell"))
	if w.Code != http.StatusNotFound {
		t.Fatalf("unknown attachment = %d, want 404", w.Code)
	}
	w, _ = putChunk(t, h, "dev-2", "att-1", 2, []byte("rld"))
	if w.Code != http.StatusForbidden {
		t.Fatalf("non-creator chunk = %d, want 403", w.Code)
	}

	// The failed writes above stored nothing: only chunks 0 and 1 exist.
	r = httptest.NewRequest(http.MethodGet, "/v1/devices/dev-1/attachments/att-1", nil)
	w = serveRecorder(h, r)
	var meta map[string]any
	_ = json.Unmarshal(w.Body.Bytes(), &meta)
	got := fmt.Sprint(meta["receivedChunks"])
	if got != "[0 1]" {
		t.Fatalf("receivedChunks = %v, want [0 1]", meta["receivedChunks"])
	}
}

func TestCompleteAttachmentHTTP(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	registerDevice(t, h, "dev-2")
	content := []byte("hello world")
	mustCreateAttachment(t, h, "dev-1", "att-1", content, 4)

	// Non-creator cannot complete.
	w, _ := completeAttachment(t, h, "dev-2", "att-1")
	if w.Code != http.StatusForbidden {
		t.Fatalf("non-creator complete = %d, want 403", w.Code)
	}
	// Unknown attachment.
	w, _ = completeAttachment(t, h, "dev-1", "nope")
	if w.Code != http.StatusNotFound {
		t.Fatalf("unknown complete = %d, want 404", w.Code)
	}

	// Missing chunks: 409, upload stays resumable.
	putChunk(t, h, "dev-1", "att-1", 0, []byte("hell"))
	w, _ = completeAttachment(t, h, "dev-1", "att-1")
	if w.Code != http.StatusConflict {
		t.Fatalf("incomplete = %d, want 409", w.Code)
	}
	assertJSONError(t, w)

	// Resume and finish.
	putChunk(t, h, "dev-1", "att-1", 1, []byte("o wo"))
	putChunk(t, h, "dev-1", "att-1", 2, []byte("rld"))
	w, body := completeAttachment(t, h, "dev-1", "att-1")
	if w.Code != http.StatusOK {
		t.Fatalf("complete = %d body=%s", w.Code, w.Body.String())
	}
	if body["attachmentId"] != "att-1" || body["complete"] != true ||
		body["size"] != float64(11) || body["sha256"] != sha256Hex(content) || body["reused"] != false {
		t.Fatalf("complete body = %v", body)
	}

	// Repeating the finish returns the same result.
	w, body2 := completeAttachment(t, h, "dev-1", "att-1")
	if w.Code != http.StatusOK || fmt.Sprint(body) != fmt.Sprint(body2) {
		t.Fatalf("repeat complete = %d %v, want %v", w.Code, body2, body)
	}

	// Metadata now reports completion.
	r := httptest.NewRequest(http.MethodGet, "/v1/devices/dev-1/attachments/att-1", nil)
	w = serveRecorder(h, r)
	var meta map[string]any
	_ = json.Unmarshal(w.Body.Bytes(), &meta)
	if meta["complete"] != true {
		t.Fatalf("meta complete = %v", meta["complete"])
	}
}

