41	func TestChangesCompactEndToEnd(t *testing.T) {
42		h, _ := newTestHandler(t)
43		registerDevice(t, h, "dev-1")
44		postDocChanges(t, h, "doc", "dev-1", 3)
45	
46		// Snapshot at cursor 2, so the compaction boundary is 2.
47		w, _ := postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 2, "state": map[string]any{"s": 1}})
48		if w.Code != http.StatusOK {
49			t.Fatalf("snapshot: %d %s", w.Code, w.Body.String())
50		}
51	
52		w = compactChanges(t, h, "doc", "dev-1")
53		if w.Code != http.StatusOK {
54			t.Fatalf("compact = %d %s", w.Code, w.Body.String())
55		}
56		if got := w.Body.String(); got != "{\"boundary\":2,\"removed\":2}\n" {
57			t.Fatalf("compact body = %q", got)
58		}
59		if ct := w.Header().Get("Content-Type"); ct != "application/json" {
60			t.Fatalf("compact content type = %q", ct)
61		}
62	
63		// Only the online tail is readable, in cursor order.
64		w, body := doRequest(t, h, http.MethodGet, "/v1/documents/doc/changes?after=0")
65		if w.Code != http.StatusOK {
66			t.Fatal(w.Body.String())
67		}
68		rows := body["changes"].([]any)
69		if len(rows) != 1 {
70			t.Fatalf("changes after compact = %v", rows)
71		}
72		row := rows[0].(map[string]any)
73		if row["id"] != "c3" || row["deviceId"] != "dev-1" || int64(row["cursor"].(float64)) != 3 {
74			t.Fatalf("remaining row = %v", row)
75		}
76		if next := int64(body["nextCursor"].(float64)); next != 3 {
77			t.Fatalf("nextCursor = %d, want 3", next)
78		}
79	
80		// An empty page inside the trimmed range reports the boundary, not after.
81		_, body = doRequest(t, h, http.MethodGet, "/v1/documents/doc/changes?after=3")
82		if got := body["changes"].([]any); len(got) != 0 {
83			t.Fatalf("changes after 3 = %v", got)
84		}
85		if next := int64(body["nextCursor"].(float64)); next != 3 {
86			t.Fatalf("nextCursor after 3 = %d, want 3", next)
87		}
88	
89		// Repeating the compaction is not an error: same boundary, zero removed.
90		w = compactChanges(t, h, "doc", "dev-1")
91		if w.Code != http.StatusOK || w.Body.String() != "{\"boundary\":2,\"removed\":0}\n" {
92			t.Fatalf("re-compact = %d %q", w.Code, w.Body.String())
93		}
94	
95		// The cursor space continues past the pre-compaction maximum.
96		w, body = postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
97			"deviceId": "dev-1",
98			"changes":  []any{map[string]any{"id": "c4", "payload": map[string]any{"n": 4}}},
99		})
100		if w.Code != http.StatusOK {
101			t.Fatalf("post after compact: %d %s", w.Code, w.Body.String())
102		}
103		result := body["results"].([]any)[0].(map[string]any)
104		if result["created"] != true || int64(result["cursor"].(float64)) != 4 {
105			t.Fatalf("new change result = %v, want created cursor 4", result)
106		}
