		t.Fatalf("restore: %d %s", w.Code, w.Body.String())
	}
	w, _ = postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 3, "state": nil})
	if w.Code != http.StatusOK {
		t.Fatal(w.Body.String())
	}
